use super::*;
use semio_framework_job::{StepContextOwner,StepBudget,OperationId,Generation,root_cancel_token};
use semio_os_flow_host_source::work::FlowEvaluationCompletion;
use semio_framework_value::retirement::{RetireOwned,controlled::ControlledRetirement};
fn observe<T>(f:impl FnOnce()->T)->(T,usize,usize){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(!heap.overflowed);(value,heap.requested_bytes,heap.released_bytes)}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64.max(d.copy_bytes),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
struct Caller{owner:StepContextOwner,sequence:u64,cancel:semio_framework_job::CancelToken,receipt:RetainedCloneProgress}
impl Caller{
 fn new()->Self{Self::new_for(707)}
 fn new_for(operation:u64)->Self{let(owner,_)=StepContextOwner::new(OperationId(operation),Generation(9),RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:StepContextOwner::birth_bytes(),maximum_depth:1,..Default::default()}).unwrap();Self{owner,sequence:0,cancel:root_cancel_token(),receipt:Default::default()}}
 fn run<T>(&mut self,g:RetainedCloneGrant,f:impl FnOnce(&mut semio_framework_job::StepContext<'_>)->T)->T{let mut receipt=Default::default();let mut cx=self.owner.context(StepBudget::new(64,u64::MAX,g),self.cancel.clone(),||Some(1),&mut self.sequence,&mut receipt).unwrap();let result=f(&mut cx);self.receipt=cx.retained_progress();assert!(self.receipt.fits(g));result}
}
impl Drop for Caller{fn drop(&mut self){self.owner.close_step(RetainedCloneGrant{maximum_items:1,maximum_release_bytes:StepContextOwner::birth_bytes(),maximum_depth:1,..Default::default()});assert!(self.owner.terminal_is_empty())}}
fn close<T:RetireOwned>(value:T,births:&mut usize,releases:&mut usize){let(mut owner,b,f)=observe(||ControlledRetirement::new(value).unwrap_or_else(|_|unreachable!()));assert_eq!((b,f),(0,0));for _ in 0..1_000_000{if owner.terminal_is_empty(){break}let g=grant(owner.selected_demand(64).unwrap());let(step,b,f)=observe(||owner.step(g).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!((b,f),(p.retained_capacity_bytes,p.released_bytes));*births+=b;*releases+=f;}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)),((),0,0));}
#[derive(semio_framework_value::RetireOwned)]
struct OriginalSources{snapshot:FlowHostSnapshot,foreign:FlowHostSnapshot,infos:Arc<HistoryFoldIndex<String,OperatorInfo>>,registry:neural::SharedRegistry}
#[test]
fn original_work_publication_preserves_genuine_completion_and_all_physical_owners(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for cancel_at in [None,Some(0),Some(5),Some(37),Some(101)]{
  let((sources,mut session,mut registry_retirement),b,f)=observe(||{let snapshot:FlowHostSnapshot=semio_framework_pack_json::from_json_str(&fixture["source"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let(registry,retirement)=neural::SharedRegistry::new(neural::Registry::new());let mut session=FlowEvalSession::new().with_operator_registry(registry.clone());session.window_tick_latches.insert(1,FlowEvalWindowTickLatch{armed:true,in_flight:1,owed:true,unfinished:true});session.extension_evaluate_fault=Some(ExtensionEvaluateFault{extension_id:"original".into(),capability:"evaluate".into(),code:"fault".into(),message:"original fault 雪".into()});session.retain_invocation_origin_cold(FlowInvocationOriginLease::from_cold(FlowInvocationOrigin{window_id:"original-window".into(),window_kind_id:"original-kind".into(),neuron_id:"original-neuron".into(),extension_id:"original-extension".into(),operator_id:"original-operator".into(),node_hash:77,input_json:"{\"original\":true}".into(),dependency_json:"{}".into(),operator_version:"original-version".into(),outer_node_hash:None,preview_source:None}));let foreign=snapshot.clone();(OriginalSources{snapshot,foreign,infos:Arc::new(HistoryFoldIndex::new()),registry},session,retirement)});let original=b-f;assert!(original>0);let(mut births,mut releases)=(0,0);let pointer=sources.snapshot.widgets.as_ptr();let origin_pointer=session.invocation_origin_at(0).unwrap().input_json.as_ptr();let fault_pointer=session.extension_evaluate_fault().unwrap().message.as_ptr();let mut caller=Caller::new();let(mut work,b,f)=observe(||session.evaluation_work(sources.infos.clone(),19).unwrap());assert_eq!((b,f),(0,0));let mut output:Option<FlowEvaluationCompletion>=None;
  for _ in 0..1_000_000{let g=grant(work.next_demands(&sources.snapshot,64).unwrap());let(result,b,f)=observe(||caller.run(g,|cx|work.step(&sources.snapshot,cx)).unwrap());let p=caller.receipt;assert_eq!((b,f),(p.retained_capacity_bytes,p.released_bytes));births+=b;releases+=f;if result.is_some(){output=result;break}}
  let output=output.expect("genuine original Work must return its completion");work.begin_close();for _ in 0..1_000_000{if work.terminal_is_empty(){break}let g=grant(work.next_close_demands(64).unwrap());let(step,b,f)=observe(||work.close_step(g).unwrap());let p=step.progress();assert_eq!((b,f),(p.retained_capacity_bytes,p.released_bytes));births+=b;releases+=f;}assert!(work.terminal_is_empty());assert_eq!(observe(||drop(work)),((),0,0));
  let cold_text=build_channel_eval_json(&sources.snapshot,&output.channels,&sources.infos);let(mut publication,b,f)=observe(||FlowWorkPublication::new(output,&sources.snapshot,707,9));assert_eq!((b,f),(0,0));let(rejected,b,f)=observe(||caller.run(RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()},|cx|publication.step(&sources.foreign,&sources.infos,&mut session,cx)));assert!(rejected.is_err());assert_eq!((b,f),(0,0));assert_eq!(caller.receipt,Default::default());let mut foreign_caller=Caller::new_for(708);let(rejected,b,f)=observe(||foreign_caller.run(RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()},|cx|publication.step(&sources.snapshot,&sources.infos,&mut session,cx)));assert!(rejected.is_err());assert_eq!(foreign_caller.receipt,Default::default());assert_eq!((b,f),(0,0));drop(foreign_caller);let mut done=false;
  for turn in 0..1_000_000{if cancel_at==Some(turn){let(_,b,f)=observe(||caller.cancel.cancel_now());assert_eq!((b,f),(0,0));let(result,b,f)=observe(||caller.run(grant(publication.next_demands(&sources.snapshot,&sources.infos,&session,64).unwrap()),|cx|{assert!(cx.is_cancelled());publication.step(&sources.snapshot,&sources.infos,&mut session,cx)}).unwrap());assert!(!result);assert_eq!(caller.receipt,Default::default());assert_eq!((b,f),(0,0));break}let d=publication.next_demands(&sources.snapshot,&sources.infos,&session,64).unwrap();let g=grant(d);
   for denied in [Some(RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0).then(||RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g}),(d.capacity_bytes>0).then(||RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g}),(d.release_bytes>0).then(||RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g}),(d.depth>0).then(||RetainedCloneGrant{maximum_depth:d.depth-1,..g})].into_iter().flatten(){let(result,b,f)=observe(||caller.run(denied,|cx|publication.step(&sources.snapshot,&sources.infos,&mut session,cx)).unwrap());assert!(!result);assert_eq!(caller.receipt,Default::default());assert_eq!((b,f),(0,0));}
   let(result,b,f)=observe(||caller.run(g,|cx|publication.step(&sources.snapshot,&sources.infos,&mut session,cx)).unwrap());let p=caller.receipt;assert_eq!(publication.step_progress(),p);assert_eq!((b,f),(p.retained_capacity_bytes,p.released_bytes));births+=b;releases+=f;assert_eq!(sources.snapshot.widgets.as_ptr(),pointer);assert_eq!(session.invocation_origin_at(0).unwrap().input_json.as_ptr(),origin_pointer);assert_eq!(session.extension_evaluate_fault().unwrap().message.as_ptr(),fault_pointer);assert_eq!(session.window_tick_latches.get(&1),Some(&FlowEvalWindowTickLatch{armed:true,in_flight:1,owed:true,unfinished:true}));if result{done=true;break}
  }
  if cancel_at.is_none(){assert!(done);assert_eq!(session.eval_json(),cold_text);assert_eq!(serde_json::from_str::<serde_json::Value>(session.eval_json()).unwrap(),fixture["expected"]);assert_eq!(session.painted_eval_json(),session.eval_json());assert_eq!(session.converged_eval_json(),session.eval_json());let(pending,b,f)=observe(||publication.take_pending(RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()}).unwrap());assert!(pending.0.is_empty());assert_eq!((b,f),(0,0));}
  publication.begin_close();for _ in 0..1_000_000{if publication.terminal_is_empty(){break}let g=grant(publication.next_close_demands(64).unwrap());let(step,b,f)=observe(||publication.close_step(g).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!((b,f),(p.retained_capacity_bytes,p.released_bytes));births+=b;releases+=f;}assert!(publication.terminal_is_empty());assert_eq!(observe(||drop(publication)),((),0,0));
  session.begin_close();for _ in 0..1_000_000{if session.terminal_is_empty(){break}let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:session.next_close_capacity_byte_demand(64).unwrap(),maximum_release_bytes:session.next_close_release_byte_demand().unwrap(),maximum_depth:session.next_close_depth_demand().unwrap()};let(step,b,f)=observe(||session.close_step(g).unwrap());let p=match step{semio_framework_job::InteractiveJobCloseStep::Pending{progress}|semio_framework_job::InteractiveJobCloseStep::Complete{progress}=>progress,_=>panic!("funded session close refused")};assert_eq!((b,f),(p.retained_capacity_bytes,p.released_bytes));births+=b;releases+=f;}assert!(session.terminal_is_empty());assert_eq!(observe(||drop(session)),((),0,0));close(sources,&mut births,&mut releases);
  for _ in 0..1_000_000{if registry_retirement.terminal_is_empty(){break}let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:registry_retirement.next_capacity_byte_demand(64).unwrap(),maximum_release_bytes:registry_retirement.next_release_byte_demand().unwrap(),maximum_depth:registry_retirement.next_depth_demand().unwrap()};let(step,b,f)=observe(||registry_retirement.close_step(g).unwrap());let p=step.progress();assert_eq!((b,f),(p.retained_capacity_bytes,p.released_bytes));births+=b;releases+=f;}assert!(registry_retirement.terminal_is_empty());assert_eq!(original+births,releases,"[DEBUG] cancel={cancel_at:?} original={original} births={births} releases={releases}; registry={} cache={} infos={} work={}",size_of::<neural::Registry>(),size_of::<neural::NeuralCache>(),size_of::<HistoryFoldIndex<String,OperatorInfo>>(),size_of::<FlowEvaluationWork>());assert_eq!(observe(||drop(registry_retirement)),((),0,0));
 }
}

#[test]
fn original_work_publication_paint_matches_independent_unanswered_and_fault_rows(){
 use semio_os_flow_host_source::paint::FlowPaintCursor;
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["paintCases"].as_array().unwrap(){
  let((snapshot,infos,channels,text,mut cursor),b,f)=observe(||{let mut source=fixture["source"].clone();source["widgets"][0]["id"]="node".into();let snapshot:FlowHostSnapshot=semio_framework_pack_json::from_json_str(&source.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let input:Dictionary=semio_framework_pack_json::from_json_str(&row["live"]["node"]["in"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let output:Dictionary=semio_framework_pack_json::from_json_str(&row["live"]["node"]["out"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();(snapshot,HistoryFoldIndex::<String,OperatorInfo>::new(),EvalChannels{inputs:[("node".into(),input)].into_iter().collect(),outputs:[("node".into(),output)].into_iter().collect()},row["converged"].to_string(),FlowPaintCursor::new())});let original=b-f;let cold=merge_unanswered_eval_entries(&row["live"].to_string(),&text,&snapshot);assert_eq!(serde_json::from_str::<serde_json::Value>(&cold).unwrap(),row["expected"]);let(mut births,mut releases)=(0,0);let mut output=None;
  for _ in 0..1_000_000{let d=cursor.demands(&snapshot,&channels,&infos,&text).unwrap();let g=grant(d);let(result,b,f)=observe(||cursor.step(&snapshot,&channels,&infos,&text,RetainedCloneGrant{maximum_items:0,..g}).unwrap());assert!(result.is_none());assert_eq!(cursor.step_progress(),Default::default());assert_eq!((b,f),(0,0));let(result,b,f)=observe(||cursor.step(&snapshot,&channels,&infos,&text,g).unwrap());let p=cursor.step_progress();assert!(p.fits(g));assert_eq!((b,f),(p.retained_capacity_bytes,p.released_bytes));births+=b;releases+=f;if result.is_some(){output=result;break}}
  let output=output.expect("funded canonical painting must complete");assert_eq!(serde_json::from_str::<serde_json::Value>(&output).unwrap(),row["expected"]);close(((cursor,snapshot,infos),(channels,text,output)),&mut births,&mut releases);assert_eq!(original+births,releases);
 }
}

fn profile_native<T>(caller:&mut semio_framework_job::OriginalJobFixtureCaller,decoder:Option<&mut semio_framework_job::OriginalJobDecodeOwner>,stock:RetainedCloneGrant,births:&mut usize,releases:&mut usize,run:impl FnOnce(&mut semio_framework_job::StepContext<'_>)->Result<T,semio_framework_job::OriginalTurnFailure>)->T{
 let(answer,b,f)=observe(||match decoder{Some(decoder)=>caller.turn_with_decoder(stock,decoder,run),None=>caller.turn(stock,run)});let p=caller.receipt();assert_eq!((b,f),(p.retained_capacity_bytes,p.released_bytes));*births+=b;*releases+=f;answer.unwrap()
}
fn profile_close<T:RetireOwned>(value:T,caller:&mut semio_framework_job::OriginalJobFixtureCaller,decoder:&mut semio_framework_job::OriginalJobDecodeOwner,stock:RetainedCloneGrant,turns:&mut usize,births:&mut usize,releases:&mut usize){
 let(mut owner,b,f)=observe(||ControlledRetirement::new(value).unwrap_or_else(|_|unreachable!()));assert_eq!((b,f),(0,0));
 for _ in 0..32768{if owner.terminal_is_empty(){break}*turns+=1;profile_native(caller,Some(decoder),stock,births,releases,|cx|cx.with_original_retirement(|cx|{for _ in 0..512{let before=cx.retained_progress();let d=owner.selected_demand(cx.retained_grant().maximum_copy_bytes)?;semio_framework_job::close_original_retained_step(cx,d,|g|{let result=owner.step(g);semio_framework_value::RetainedWorkOutcome{result,work:owner.last_turn_work()}})?;if owner.terminal_is_empty()||cx.should_yield()||cx.retained_progress()==before{break}}Ok(())}));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)),((),0,0));
}
#[test]
fn original_work_publication_fits_original_editor_opportunity_without_new_funding(){
 use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,close_original_retained_step};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let policy:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/🧪️testing/🎟️caller/🧪️tests/🧫️fixtures/🎟️caller.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();let fuel=policy["fuel"].as_u64().unwrap();assert_eq!(fuel,32768);assert_eq!(policy["clockUs"],1000);assert_eq!(policy["deadlineUs"],1500);
 let((sources,mut session,mut registry_retirement),b,f)=observe(||{let snapshot:FlowHostSnapshot=semio_framework_pack_json::from_json_str(&fixture["source"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let foreign=snapshot.clone();let(registry,retirement)=neural::SharedRegistry::new(neural::Registry::new());let session=FlowEvalSession::new().with_operator_registry(registry.clone());(OriginalSources{snapshot,foreign,infos:Arc::new(HistoryFoldIndex::new()),registry},session,retirement)});let original=b-f;let(mut births,mut releases,mut turns)=(0,0,0);let operation=policy["operation"].as_u64().unwrap();let generation=policy["generation"].as_u64().unwrap();let mut caller=OriginalJobFixtureCaller::admit(OperationId(operation),Generation(generation),stock,||Some(1000),1500,fuel);let mut decoder=OriginalJobDecodeOwner::empty();let(mut work,b,f)=observe(||session.evaluation_work(sources.infos.clone(),19).unwrap());assert_eq!((b,f),(0,0));let mut output=None;
 for _ in 0..32768{turns+=1;let step=profile_native(&mut caller,Some(&mut decoder),stock,&mut births,&mut releases,|cx|{assert_eq!(cx.operation(),OperationId(operation));assert_eq!(cx.generation(),Generation(generation));assert_eq!(cx.deadline_us(),1500);Ok(work.step(&sources.snapshot,cx))}).unwrap();if step.is_some(){output=step;break}}let output=output.expect("original retained evaluation must produce its completion");let(mut publication,b,f)=observe(||FlowWorkPublication::new(output,&sources.snapshot,operation,generation));assert_eq!((b,f),(0,0));
 for _ in 0..32768{turns+=1;if profile_native(&mut caller,Some(&mut decoder),stock,&mut births,&mut releases,|cx|publication.step(&sources.snapshot,&sources.infos,&mut session,cx)){break}}assert!(publication.is_complete());assert_eq!(serde_json::from_str::<serde_json::Value>(session.eval_json()).unwrap(),fixture["expected"]);
 profile_close(work,&mut caller,&mut decoder,stock,&mut turns,&mut births,&mut releases);publication.begin_close();
 for _ in 0..32768{if publication.terminal_is_empty(){break}turns+=1;profile_native(&mut caller,Some(&mut decoder),stock,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|{for _ in 0..512{let before=cx.retained_progress();let d=publication.next_close_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|{let result=publication.close_step(g);semio_framework_value::RetainedWorkOutcome{result,work:publication.last_turn_work()}})?;if publication.terminal_is_empty()||cx.should_yield()||cx.retained_progress()==before{break}}Ok(())}));}assert!(publication.terminal_is_empty());assert_eq!(observe(||drop(publication)),((),0,0));session.begin_close();
 for _ in 0..32768{if session.terminal_is_empty(){break}turns+=1;profile_native(&mut caller,Some(&mut decoder),stock,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|{for _ in 0..512{let before=cx.retained_progress();let copy=cx.retained_grant().maximum_copy_bytes;let d=RetirementDemand{copy_bytes:session.next_close_copy_byte_demand()?,capacity_bytes:session.next_close_capacity_byte_demand(copy)?,release_bytes:session.next_close_release_byte_demand()?,depth:session.next_close_depth_demand()?};close_original_retained_step(cx,d,|g|session.retire_source_step(g))?;if session.terminal_is_empty()||cx.should_yield()||cx.retained_progress()==before{break}}Ok(())}));}assert!(session.terminal_is_empty());assert_eq!(observe(||drop(session)),((),0,0));profile_close(sources,&mut caller,&mut decoder,stock,&mut turns,&mut births,&mut releases);
 for _ in 0..32768{if registry_retirement.terminal_is_empty(){break}turns+=1;profile_native(&mut caller,Some(&mut decoder),stock,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|{for _ in 0..512{let before=cx.retained_progress();let copy=cx.retained_grant().maximum_copy_bytes;let d=RetirementDemand{copy_bytes:registry_retirement.next_copy_byte_demand()?,capacity_bytes:registry_retirement.next_capacity_byte_demand(copy)?,release_bytes:registry_retirement.next_release_byte_demand()?,depth:registry_retirement.next_depth_demand()?};close_original_retained_step(cx,d,|g|{let result=registry_retirement.close_step(g);semio_framework_value::RetainedWorkOutcome{result,work:registry_retirement.last_turn_work()}})?;if registry_retirement.terminal_is_empty()||cx.should_yield()||cx.retained_progress()==before{break}}Ok(())}));}assert!(registry_retirement.terminal_is_empty());assert_eq!(observe(||drop(registry_retirement)),((),0,0));
 while !decoder.terminal_is_empty(){turns+=1;profile_native(&mut caller,None,stock,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|{for _ in 0..512{let before=cx.retained_progress();let d=decoder.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;decoder.close_on_source(cx)?;if decoder.terminal_is_empty()||cx.should_yield()||cx.retained_progress()==before{break}}Ok(())}));}
 assert_eq!(observe(||drop(decoder)),((),0,0));assert_eq!(original+births,releases,"[DEBUG] original={original} births={births} releases={releases} turns={turns}; registry={} cache={} infos={} work={}",size_of::<neural::Registry>(),size_of::<neural::NeuralCache>(),size_of::<HistoryFoldIndex<String,OperatorInfo>>(),size_of::<FlowEvaluationWork>());assert_eq!(caller.stock(),stock);while !caller.terminal_is_empty(){turns+=1;caller.retire_step(stock).unwrap();}let spent=fuel-caller.fuel_remaining();caller.retire(stock);assert!(turns<fixture["maximumRootCalls"].as_u64().unwrap()as usize,"original Work publication spent {turns} calls");assert!(spent<32000,"original Work publication spent {spent} fuel");
}

#[test]
fn original_work_publication_generation_read_does_not_construct_unowned_registry() {
 let(generation,births,releases)=observe(semio_os_flow_operators::flow_extension_registry_generation);
 assert_eq!((births,releases),(0,0),"generation observation must not construct process-owned registry storage");
 let(next,births,releases)=observe(semio_os_flow_operators::flow_extension_registry_generation);
 assert_eq!(next,generation);assert_eq!((births,releases),(0,0));
}
